function b() {
  function sanitize(el) {
    if (!el) return;
    var e = el.value || "";
    if (el.hasAttribute("rm-white-spaces")) {
      e = e.replace(/\s+/g, "");
    }
    if (el.hasAttribute("to-lower")) {
      e = e.toLowerCase();
    }
    if (el.hasAttribute("to-upper")) {
      e = e.toUpperCase();
    }
    if (el.hasAttribute("to-arabic-numbers") || el.hasAttribute("to-english-numbers") || el.hasAttribute("username-field")) {
      e = e
        .replace(/[\u0660\u06F0]/g, "0")
        .replace(/[\u0661\u06F1]/g, "1")
        .replace(/[\u0662\u06F2]/g, "2")
        .replace(/[\u0663\u06F3]/g, "3")
        .replace(/[\u0664\u06F4]/g, "4")
        .replace(/[\u0665\u06F5]/g, "5")
        .replace(/[\u0666\u06F6]/g, "6")
        .replace(/[\u0667\u06F7]/g, "7")
        .replace(/[\u0668\u06F8]/g, "8")
        .replace(/[\u0669\u06F9]/g, "9")
        .replace(/:/g, "0");
    }
    if (el.hasAttribute("only-numbers")) {
      e = e.replace(/\D/g, "");
    }
    if (el.hasAttribute("no-numbers")) {
      e = e.replace(/[0-9]/g, "");
    }
    if (el.hasAttribute("only-alphanumeric")) {
      e = e.replace(/[^0-9a-z]/gi, "");
    }
    if (el.value !== e) {
      var start = el.selectionStart;
      var end = el.selectionEnd;
      el.value = e;
      try {
        if (start !== null && end !== null) {
          el.setSelectionRange(start, end);
        }
      } catch (err) {}
    }
  }

  var targets = document.querySelectorAll("input[improve-input], input[username-field], input[password-field]");
  targets.forEach(function (inputEl) {
    ["input", "paste", "change", "keyup", "blur"].forEach(function (evt) {
      inputEl.addEventListener(evt, function () {
        var self = this;
        sanitize(self);
        setTimeout(function () {
          sanitize(self);
        }, 15);
      });
    });
  });
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", b, false);
} else {
  b();
}
